ALTER TABLE cabinet_items ADD COLUMN parent_item_id UUID REFERENCES cabinet_items(id) ON DELETE RESTRICT, ADD COLUMN position INTEGER NOT NULL DEFAULT 0 CHECK(position >= 0), ADD COLUMN page_policy JSONB, ADD COLUMN user_members INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[], ADD COLUMN bear_members UUID[] NOT NULL DEFAULT ARRAY[]::UUID[], ADD COLUMN reviewer_user_ids INTEGER[] NOT NULL DEFAULT ARRAY[]::INTEGER[];
ALTER TABLE cabinet_items ADD CONSTRAINT cabinet_page_policy_object CHECK(page_policy IS NULL OR jsonb_typeof(page_policy) = 'object');
CREATE INDEX cabinet_items_parent_position ON cabinet_items(parent_item_id, position, id);
CREATE TABLE cabinet_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), item_id UUID NOT NULL REFERENCES cabinet_items(id), version_id UUID NOT NULL REFERENCES cabinet_item_versions(id), reviewer_user_id INTEGER NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), rationale TEXT NOT NULL CHECK(btrim(rationale) <> ''), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(version_id));
